package com.rsd.middle.drawdown;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 提款业务单（阶段 2：单收款人，支付信息直接挂在本单上；阶段 4 多收款人引入 PaymentInstruction 子表，
 * 一个业务单对应多条支付指令、多个成功批次形成多笔借据）。
 * 状态机见 docs/接口契约-阶段2.md §2；"外部已付款成功、中台入账未完成"是显式可恢复状态。
 */
@Entity
@Table(name = "drawdown_order")
public class DrawdownOrder {

    public enum Status { PROCESSING, EXTERNAL_SUCCESS_BOOKING_PENDING, SUCCESS, FAILED, CANCELLED }

    /** 外部付款指令状态（本单一条指令）。 */
    public enum PaymentStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    /** 中台入账（Fineract 放款登记）状态。 */
    public enum BookingStatus { NONE, TO_BOOK, BOOKED, RETRY_NEEDED }

    @Id
    private String bizOrderNo;
    private String creditId;
    private String quoteNo;
    private String productId;
    private BigDecimal amount;
    private String payeeName;
    private String payeeAccount;
    private String purpose;

    private Status status;
    private PaymentStatus paymentStatus;
    private String extSerialNo;
    private BookingStatus bookingStatus;
    private Integer bookingRetryCount;
    private String bookingLastError;
    private String loanAccountNo;       // Fineract 借据 id，创建成功即写入（放款前即存在）
    private BigDecimal bookedAmount;    // 实际入账金额
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public boolean terminal() {
        return status == Status.SUCCESS || status == Status.FAILED || status == Status.CANCELLED;
    }

    public String getBizOrderNo() { return bizOrderNo; }
    public void setBizOrderNo(String bizOrderNo) { this.bizOrderNo = bizOrderNo; }
    public String getCreditId() { return creditId; }
    public void setCreditId(String creditId) { this.creditId = creditId; }
    public String getQuoteNo() { return quoteNo; }
    public void setQuoteNo(String quoteNo) { this.quoteNo = quoteNo; }
    public String getProductId() { return productId; }
    public void setProductId(String productId) { this.productId = productId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public String getPayeeName() { return payeeName; }
    public void setPayeeName(String payeeName) { this.payeeName = payeeName; }
    public String getPayeeAccount() { return payeeAccount; }
    public void setPayeeAccount(String payeeAccount) { this.payeeAccount = payeeAccount; }
    public String getPurpose() { return purpose; }
    public void setPurpose(String purpose) { this.purpose = purpose; }
    public Status getStatus() { return status; }
    public void setStatus(Status status) { this.status = status; }
    public PaymentStatus getPaymentStatus() { return paymentStatus; }
    public void setPaymentStatus(PaymentStatus paymentStatus) { this.paymentStatus = paymentStatus; }
    public String getExtSerialNo() { return extSerialNo; }
    public void setExtSerialNo(String extSerialNo) { this.extSerialNo = extSerialNo; }
    public BookingStatus getBookingStatus() { return bookingStatus; }
    public void setBookingStatus(BookingStatus bookingStatus) { this.bookingStatus = bookingStatus; }
    public Integer getBookingRetryCount() { return bookingRetryCount; }
    public void setBookingRetryCount(Integer bookingRetryCount) { this.bookingRetryCount = bookingRetryCount; }
    public String getBookingLastError() { return bookingLastError; }
    public void setBookingLastError(String bookingLastError) { this.bookingLastError = bookingLastError; }
    public String getLoanAccountNo() { return loanAccountNo; }
    public void setLoanAccountNo(String loanAccountNo) { this.loanAccountNo = loanAccountNo; }
    public BigDecimal getBookedAmount() { return bookedAmount; }
    public void setBookedAmount(BigDecimal bookedAmount) { this.bookedAmount = bookedAmount; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.rsd.middle.fineract;

import com.rsd.middle.common.BizException;
import com.rsd.middle.common.Ids;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Map;

/**
 * Fineract REST 适配层：中台唯一允许触 Fineract 的模块（docs/三系统边界设计.md §5）。
 * 端点与命令语义对应 Fineract 1.14.0：LoansApiResource(/v1/loans)、LoanTransactionsApiResource(/v1/loans/{id}/transactions)。
 * 审批命令本设计不需要单独调用：中台创建借据即审批放款一体（受托支付成功才登记），
 * 因此创建时直接提交为经审批口径（submittedOnDate+approvedOnDate），放款在支付确认后执行。
 */
@Component
@EnableConfigurationProperties(FineractProperties.class)
public class FineractClient {

    private static final Logger log = LoggerFactory.getLogger(FineractClient.class);

    private final FineractProperties props;
    private final RestClient http;

    public FineractClient(FineractProperties props) {
        this.props = props;
        String auth = Base64.getEncoder().encodeToString(
                (props.username() + ":" + props.password()).getBytes(StandardCharsets.UTF_8));
        this.http = RestClient.builder()
                .baseUrl(props.baseUrl())
                .defaultHeader(HttpHeaders.AUTHORIZATION, "Basic " + auth)
                .defaultHeader("Fineract-Platform-TenantId", props.tenantId())
                .defaultHeader(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)
                .build();
    }

    /** 中台还款方式 → Fineract amortizationType（AmortizationMethod：0=EQUAL_PRINCIPAL，1=EQUAL_INSTALLMENTS）。 */
    public static int amortizationType(String repaymentMode) {
        return switch (repaymentMode) {
            case "EQUAL_PRINCIPAL" -> 0;
            case "EQUAL_INSTALLMENTS" -> 1;
            default -> throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        };
    }

    /** 创建借据（贷款申请）。返回 Fineract loanId。 */
    @SuppressWarnings("unchecked")
    public String createLoan(String fineractProductId, BigDecimal principal, int termMonths,
                             String repaymentMode, String firstRepaymentDate) {
        Map<String, Object> payload = Map.ofEntries(
                Map.entry("productId", Long.valueOf(fineractProductId)),
                Map.entry("principal", principal),
                Map.entry("loanTermFrequency", termMonths),
                Map.entry("loanTermFrequencyType", 2),          // 2=MONTHS（PeriodFrequencyType）
                Map.entry("repaymentEvery", 1),
                Map.entry("repaymentFrequencyType", 2),
                Map.entry("interestType", 0),                   // 0=DECLINING_BALANCE
                Map.entry("interestCalculationPeriodMethod", 1),// 1=SAME_AS_REPAYMENT_PERIOD
                Map.entry("amortizationType", amortizationType(repaymentMode)),
                Map.entry("transactionProcessingStrategyCode", "mifos-standard-strategy"),
                Map.entry("submittedOnDate", Ids.now().toLocalDate().toString()),
                Map.entry("expectedDisbursementDate", Ids.now().toLocalDate().toString()),
                Map.entry("repaymentStartDateType", 1),         // 1=DISBURSEMENT_DATE
                Map.entry("dateFormat", Ids.DATE_FMT),
                Map.entry("locale", "en"));
        Map<String, Object> resp = http.post().uri("/loans")
                .body(payload)
                .retrieve().body(Map.class);
        log.info("fineract createLoan -> {}", resp);
        return String.valueOf(resp.get("loanId"));
    }

    /** 借据当前状态（幂等判定用：放款重试前先看是否已 ACTIVE）。 */
    @SuppressWarnings("unchecked")
    public boolean isLoanActive(String loanAccountNo) {
        Map<String, Object> loan = http.get().uri("/loans/{id}", loanAccountNo).retrieve().body(Map.class);
        Map<String, Object> status = (Map<String, Object>) loan.get("status");
        return Boolean.TRUE.equals(status.get("active"));
    }

    /** 放款登记（command=disburse）。真实放款金额与放款日由此固定为借据起息依据。 */
    public void disburseLoan(String loanAccountNo, BigDecimal amount) {
        http.post().uri(uri -> uri.path("/loans/{id}").queryParam("command", "disburse").build(loanAccountNo))
                .body(Map.of("transactionAmount", amount,
                        "note", "融商贷受托支付放款",
                        "dateFormat", Ids.DATE_FMT, "locale", "en"))
                .retrieve().toBodilessEntity();
    }

    /** 试算还款计划（command=calculateLoanSchedule，不创建账户）。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> calculateLoanSchedule(String fineractProductId, BigDecimal principal, int termMonths,
                                                     String repaymentMode, String firstRepaymentDate) {
        Map<String, Object> payload = Map.of(
                "productId", Long.valueOf(fineractProductId),
                "principal", principal,
                "loanTermFrequency", termMonths,
                "loanTermFrequencyType", 2,
                "repaymentEvery", 1,
                "repaymentFrequencyType", 2,
                "interestType", 0,
                "interestCalculationPeriodMethod", 1,
                "amortizationType", amortizationType(repaymentMode),
                "transactionProcessingStrategyCode", "mifos-standard-strategy",
                "expectedDisbursementDate", Ids.now().toLocalDate().toString(),
                "repaymentStartDateType", 1,
                "dateFormat", Ids.DATE_FMT, "locale", "en",
                "command", "calculateLoanSchedule");
        return http.post().uri("/loans").body(payload).retrieve().body(Map.class);
    }

    /** 提前结清/部分还本试算（GET /loans/{id}?command=calculatePrepayment）。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> calculatePrepayment(String loanAccountNo, String today) {
        return http.get()
                .uri(uri -> uri.path("/loans/{id}").queryParam("command", "calculatePrepayment")
                        .queryParam("dateFormat", Ids.DATE_FMT).queryParam("locale", "en")
                        .build(loanAccountNo))
                .retrieve().body(Map.class);
    }

    /** 还款入账（POST /loans/{id}/transactions?command=repayment）。返回 Fineract 交易 id。 */
    @SuppressWarnings("unchecked")
    public String repayLoan(String loanAccountNo, BigDecimal amount) {
        Map<String, Object> resp = http.post()
                .uri(uri -> uri.path("/loans/{id}/transactions")
                        .queryParam("command", "repayment").build(loanAccountNo))
                .body(Map.of("transactionAmount", amount,
                        "transactionDate", Ids.now().toLocalDate().toString(),
                        "dateFormat", Ids.DATE_FMT, "locale", "en"))
                .retrieve().body(Map.class);
        return String.valueOf(resp.get("resourceId"));
    }

    /**
     * 还款分配明细：读取该笔交易的本金/利息/费用部分。
     * 依据 Fineract 还款交易响应中的 principalPortion/interestPortion/feeChargesPortion，
     * 中台只按本金部分恢复额度（利息费用不恢复）。
     */
    @SuppressWarnings("unchecked")
    public RepaymentAllocation getRepaymentAllocation(String loanAccountNo, String transactionId) {
        Map<String, Object> tx = http.get()
                .uri("/loans/{id}/transactions/{tx}", loanAccountNo, transactionId)
                .retrieve().body(Map.class);
        BigDecimal principal = toBigDecimal(tx.get("principalPortion"));
        BigDecimal interest = toBigDecimal(tx.get("interestPortion"));
        BigDecimal fees = toBigDecimal(tx.get("feeChargesPortion")).add(toBigDecimal(tx.get("penaltyChargesPortion")));
        return new RepaymentAllocation(transactionId, principal, interest, fees);
    }

    public record RepaymentAllocation(String transactionId, BigDecimal principalPortion,
                                      BigDecimal interestPortion, BigDecimal feePortion) {
    }

    private static BigDecimal toBigDecimal(Object value) {
        return value == null ? BigDecimal.ZERO : new BigDecimal(String.valueOf(value));
    }
}

package com.rsd.middle.drawdown;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.rsd.middle.credit.LimitService;
import com.rsd.middle.credit.ProductConfig;
import com.rsd.middle.credit.ProductConfigRepository;
import com.rsd.middle.credit.ProductConfigVersion;
import com.rsd.middle.credit.ProductConfigVersionRepository;
import com.rsd.middle.common.BizException;
import com.rsd.middle.common.Ids;
import com.rsd.middle.external.SimulatorClient;
import com.rsd.middle.fineract.FineractClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * 提款编排：报价 → 申请（逐层预占+创建借据+提交付款）→ 结果确认 → 入账（Fineract 放款+逐层实占）。
 * 状态机与异常恢复语义见 docs/接口契约-阶段2.md §6；额度按多层口径校验与记账（接口契约-阶段3.md §1）。
 * 产品规则按报价绑定的版本快照执行（ProductConfigVersion），新配置只适用于新报价。
 */
@Service
public class DrawdownService {

    private static final Logger log = LoggerFactory.getLogger(DrawdownService.class);

    private final DrawdownQuoteRepository quoteRepo;
    private final DrawdownOrderRepository orderRepo;
    private final ProductConfigRepository productRepo;
    private final ProductConfigVersionRepository versionRepo;
    private final LimitService limitService;
    private final FineractClient fineract;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

    public DrawdownService(DrawdownQuoteRepository quoteRepo, DrawdownOrderRepository orderRepo,
                           ProductConfigRepository productRepo, ProductConfigVersionRepository versionRepo,
                           LimitService limitService, FineractClient fineract, SimulatorClient simulator,
                           ObjectMapper objectMapper) {
        this.quoteRepo = quoteRepo;
        this.orderRepo = orderRepo;
        this.productRepo = productRepo;
        this.versionRepo = versionRepo;
        this.limitService = limitService;
        this.fineract = fineract;
        this.simulator = simulator;
        this.objectMapper = objectMapper;
    }

    // ------------------------------------------------------------------ 报价

    @Transactional
    public Map<String, Object> quote(String creditId, String productId, BigDecimal amount, Integer termMonths,
                                     String repaymentMode, String firstRepaymentDate) {
        ProductConfig product = product(productId);
        validateAmountAndTerm(product, amount, termMonths, repaymentMode);
        limitService.get(creditId); // 授信存在性
        Map<String, Object> trial = fineract.calculateLoanSchedule(product.getFineractProductId(),
                amount, termMonths, repaymentMode, firstRepaymentDate);

        DrawdownQuote quote = new DrawdownQuote();
        quote.setQuoteNo(Ids.next("QT-"));
        quote.setCreditId(creditId);
        quote.setProductId(productId);
        quote.setAmount(amount);
        quote.setTermMonths(termMonths);
        quote.setRepaymentMode(repaymentMode);
        quote.setFirstRepaymentDate(firstRepaymentDate);
        quote.setAnnualInterestRate(product.getAnnualInterestRate());
        quote.setValidUntil(Ids.now().plusMinutes(30));
        quote.setStatus(DrawdownQuote.Status.UNUSED);
        quote.setTrialScheduleJson(writeJson(trial));
        quote.setProductVersionId(resolveVersion(product).getVersionId());
        quoteRepo.save(quote);
        return Map.of("quoteNo", quote.getQuoteNo(),
                "productVersionId", quote.getProductVersionId(),
                "annualInterestRate", product.getAnnualInterestRate(),
                "trialSchedule", trial.get("periods") == null ? List.of() : trial.get("periods"),
                "validUntil", quote.getValidUntil().toString());
    }

    /**
     * 版本快照：产品配置当前字段与最新版本一致则复用，否则生成新版本（不可变）。
     */
    private ProductConfigVersion resolveVersion(ProductConfig product) {
        Optional<ProductConfigVersion> latest = versionRepo.findFirstByProductIdOrderByVersionDesc(product.getProductId());
        if (latest.isPresent() && sameRules(latest.get(), product)) {
            return latest.get();
        }
        ProductConfigVersion version = new ProductConfigVersion();
        version.setVersionId("PV-" + product.getProductId() + "-"
                + (latest.map(v -> v.getVersion() + 1).orElse(1)));
        version.setProductId(product.getProductId());
        version.setVersion(latest.map(v -> v.getVersion() + 1).orElse(1));
        version.setMinAmount(product.getMinAmount());
        version.setMaxAmount(product.getMaxAmount());
        version.setTerms(product.getTerms());
        version.setRepaymentModes(product.getRepaymentModes());
        version.setAnnualInterestRate(product.getAnnualInterestRate());
        version.setRequiresGuarantee(product.isRequiresGuarantee());
        version.setFineractProductId(product.getFineractProductId());
        version.setEffectiveAt(Ids.now());
        return versionRepo.save(version);
    }

    private boolean sameRules(ProductConfigVersion version, ProductConfig product) {
        return version.getMinAmount().compareTo(product.getMinAmount()) == 0
                && version.getMaxAmount().compareTo(product.getMaxAmount()) == 0
                && version.getTerms().equals(product.getTerms())
                && version.getRepaymentModes().equals(product.getRepaymentModes())
                && version.getAnnualInterestRate().compareTo(product.getAnnualInterestRate()) == 0
                && version.isRequiresGuarantee() == product.isRequiresGuarantee();
    }

    // ------------------------------------------------------------------ 申请

    @Transactional
    public DrawdownOrder apply(String quoteNo, String payeeName, String payeeAccount, String purpose) {
        DrawdownQuote quote = quoteRepo.findById(quoteNo).orElseThrow();
        if (!quote.usable(Ids.now())) {
            throw new BizException(BizException.Code.QUOTE_EXPIRED);
        }
        ProductConfigVersion version = versionRepo.findById(quote.getProductVersionId()).orElseThrow();
        validateAmountAndTerm(version, quote.getAmount(), quote.getTermMonths(), quote.getRepaymentMode());
        // 报价到提交期间条件变化必须重新校验：按多层口径、以申请时点为准
        if (limitService.availableForDrawdown(quote.getCreditId(), version.getProductId(),
                version.isRequiresGuarantee()).compareTo(quote.getAmount()) < 0) {
            throw new BizException(BizException.Code.LIMIT_INSUFFICIENT);
        }

        DrawdownOrder order = new DrawdownOrder();
        order.setBizOrderNo(Ids.next("DD-"));
        order.setCreditId(quote.getCreditId());
        order.setQuoteNo(quoteNo);
        order.setProductId(quote.getProductId());
        order.setAmount(quote.getAmount());
        order.setPayeeName(payeeName);
        order.setPayeeAccount(payeeAccount);
        order.setPurpose(purpose);
        order.setStatus(DrawdownOrder.Status.PROCESSING);
        order.setPaymentStatus(DrawdownOrder.PaymentStatus.TO_SUBMIT);
        order.setBookingStatus(DrawdownOrder.BookingStatus.NONE);
        order.setBookingRetryCount(0);
        order.setCreatedAt(Ids.now());
        order.setUpdatedAt(Ids.now());
        orderRepo.save(order);

        quote.setStatus(DrawdownQuote.Status.USED);

        // 逐层预占额度 → 创建借据（Fineract 贷款账户）→ 提交付款
        limitService.preOccupy(quote.getCreditId(), order.getBizOrderNo(), version.getProductId(),
                version.isRequiresGuarantee(), quote.getAmount());
        String loanAccountNo = fineract.createLoan(version.getFineractProductId(), quote.getAmount(),
                quote.getTermMonths(), quote.getRepaymentMode(), quote.getFirstRepaymentDate());
        order.setLoanAccountNo(loanAccountNo);
        submitPayment(order);
        return order;
    }

    /** 提交付款；同步终态就地结算，受理中等待回调或查单。 */
    public void submitPayment(DrawdownOrder order) {
        try {
            SimulatorClient.PaymentSubmission sub = simulator.submitPayment(
                    order.getBizOrderNo(), order.getPayeeName(), order.getPayeeAccount(), order.getAmount());
            order.setExtSerialNo(sub.extSerialNo());
            order.setUpdatedAt(Ids.now());
            switch (sub.status()) {
                case "SUCCESS" -> onPaymentResult(order, "SUCCESS");
                case "REJECTED" -> onPaymentResult(order, "FAILED");
                default -> order.setPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
            }
        } catch (Exception e) {
            // 提交失败保留 TO_SUBMIT，由补偿任务重试（模拟服务按 bizOrderNo 幂等）
            log.warn("付款提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
        }
    }

    // -------------------------------------------------- 外部结果确认（回调与查单共用）

    /**
     * 付款结果落业务单。幂等：业务单已终态、或该结果已生效时，直接确认不产生任何新记录。
     */
    @Transactional
    public void onPaymentResult(DrawdownOrder order, String result) {
        if (order.terminal()) {
            return; // 幂等：终态后收到的任何结果只影响外部流水，不改业务单
        }
        order.setUpdatedAt(Ids.now());
        if ("SUCCESS".equals(result)) {
            if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.SUCCESS) {
                return; // 幂等：成功已受理过
            }
            order.setPaymentStatus(DrawdownOrder.PaymentStatus.SUCCESS);
            order.setStatus(DrawdownOrder.Status.EXTERNAL_SUCCESS_BOOKING_PENDING);
            order.setBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK);
            book(order); // 同步尝试入账；失败转 RETRY_NEEDED 由补偿任务继续
        } else {
            if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.FAILED) {
                return;
            }
            order.setPaymentStatus(DrawdownOrder.PaymentStatus.FAILED);
            order.setStatus(DrawdownOrder.Status.FAILED);
            limitService.releasePreOccupied(order.getCreditId(), order.getBizOrderNo(), order.getProductId(),
                    requiresGuarantee(order.getProductId()), order.getAmount());
        }
    }

    /**
     * 中台入账：调用 Fineract 放款登记 + 逐层预占转实占。
     * 幂等：入账前先查借据是否已 ACTIVE（重复回调/查单/重试不会重复放款）。
     */
    @Transactional
    public void book(DrawdownOrder order) {
        if (order.getBookingStatus() == DrawdownOrder.BookingStatus.BOOKED) {
            return;
        }
        try {
            if (fineract.isLoanActive(order.getLoanAccountNo())) {
                log.info("借据已生效，跳过重复放款登记: {}", order.getLoanAccountNo());
            } else {
                fineract.disburseLoan(order.getLoanAccountNo(), order.getAmount());
            }
            order.setBookingStatus(DrawdownOrder.BookingStatus.BOOKED);
            order.setBookedAmount(order.getAmount());
            order.setStatus(DrawdownOrder.Status.SUCCESS);
            order.setUpdatedAt(Ids.now());
            limitService.confirmOccupy(order.getCreditId(), order.getBizOrderNo(),
                    order.getLoanAccountNo(), order.getProductId(),
                    requiresGuarantee(order.getProductId()), order.getAmount());
        } catch (Exception e) {
            order.setBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED);
            order.setBookingRetryCount(order.getBookingRetryCount() + 1);
            order.setBookingLastError(e.getMessage());
            order.setUpdatedAt(Ids.now());
            log.warn("入账失败转补偿: {} retry={}", order.getBizOrderNo(), order.getBookingRetryCount());
        }
    }

    /** 查单收敛：补偿任务对 PROCESSING 超时的指令主动查单，结果走与回调相同的处理通道。 */
    @Transactional
    public void queryAndSettle(DrawdownOrder order) {
        SimulatorClient.ExternalStatus status = simulator.query("PAYMENT", order.getExtSerialNo());
        if ("SUCCESS".equals(status.status()) || "FAILED".equals(status.status())) {
            onPaymentResult(order, status.status());
        } else if ("RESULT_UNCONFIRMED".equals(status.status())) {
            order.setPaymentStatus(DrawdownOrder.PaymentStatus.RESULT_UNCONFIRMED);
        }
    }

    // ------------------------------------------------------------------ 查询

    public Map<String, Object> detail(String bizOrderNo) {
        DrawdownOrder order = orderRepo.findById(bizOrderNo).orElseThrow();
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name(),
                "amount", order.getAmount(),
                "payments", List.of(Map.of("extSerialNo", order.getExtSerialNo() == null ? "" : order.getExtSerialNo(),
                        "status", order.getPaymentStatus().name(), "amount", order.getAmount())),
                "booking", Map.of("status", order.getBookingStatus().name(),
                        "loanAccountNo", order.getLoanAccountNo() == null ? "" : order.getLoanAccountNo(),
                        "retryCount", order.getBookingRetryCount()));
    }

    private boolean requiresGuarantee(String productId) {
        return productRepo.findById(productId).map(ProductConfig::isRequiresGuarantee).orElse(false);
    }

    private void validateAmountAndTerm(ProductConfigVersion version, BigDecimal amount, Integer termMonths, String repaymentMode) {
        if (amount.compareTo(version.getMinAmount()) < 0 || amount.compareTo(version.getMaxAmount()) > 0) {
            throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        }
        if (!version.termList().contains(termMonths)) {
            throw new BizException(BizException.Code.TERM_NOT_SUPPORTED);
        }
        if (!version.repaymentModeList().contains(repaymentMode)) {
            throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        }
    }

    private ProductConfig product(String productId) {
        return productRepo.findById(productId).orElseThrow(() -> new BizException(BizException.Code.PRODUCT_NOT_OPEN));
    }

    private String writeJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception e) {
            return "[]";
        }
    }
}

