package com.rsd.middle.drawdown;

import com.rsd.middle.credit.CreditLimitRepository;
import com.rsd.middle.credit.LimitService;
import com.rsd.middle.credit.ProductConfigRepository;
import com.rsd.middle.credit.ProductConfig;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/** 中台渠道接入 API（阶段 2 提款部分）。契约见 docs/接口契约-阶段2.md §4。 */
@RestController
@RequestMapping("/middle/api/v1/drawdowns")
public class DrawdownController {

    private final DrawdownService drawdownService;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final CreditLimitRepository creditRepo;

    public DrawdownController(DrawdownService drawdownService, LimitService limitService,
                              ProductConfigRepository productRepo, CreditLimitRepository creditRepo) {
        this.drawdownService = drawdownService;
        this.limitService = limitService;
        this.productRepo = productRepo;
        this.creditRepo = creditRepo;
    }

    public record QuoteRequest(String creditId, String productId, BigDecimal amount,
                               Integer termMonths, String repaymentMode, String firstRepaymentDate) {
    }

    public record ApplyRequest(String quoteNo, String payeeName, String payeeAccount, String purpose) {
    }

    @GetMapping("/options")
    public Map<String, Object> options(@RequestParam String creditId) {
        limitService.get(creditId);
        List<Map<String, Object>> products = productRepo.findAll().stream()
                .map(p -> Map.<String, Object>of(
                        "productId", p.getProductId(),
                        "productName", p.getProductName(),
                        "minAmount", p.getMinAmount(),
                        "maxAmount", p.getMaxAmount(),
                        "terms", p.termList(),
                        "repaymentModes", p.repaymentModeList(),
                        // 多层口径：各约束层余量取最小值（总授信/产品子额度/集团限额/担保覆盖）
                        "availableAmount", limitService.availableForDrawdown(creditId, p.getProductId(), p.isRequiresGuarantee())))
                .toList();
        return Map.of("creditId", creditId, "products", products);
    }

    @PostMapping("/quote")
    public Map<String, Object> quote(@RequestBody QuoteRequest request) {
        return drawdownService.quote(request.creditId(), request.productId(), request.amount(),
                request.termMonths(), request.repaymentMode(), request.firstRepaymentDate());
    }

    @PostMapping
    public Map<String, Object> apply(@RequestBody ApplyRequest request) {
        DrawdownOrder order = drawdownService.apply(request.quoteNo(), request.payeeName(),
                request.payeeAccount(), request.purpose());
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name());
    }

    @GetMapping("/{bizOrderNo}")
    public Map<String, Object> detail(@PathVariable String bizOrderNo) {
        return drawdownService.detail(bizOrderNo);
    }
}

