package com.rsd.channel;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import java.util.Map;

/** 客户前端接入 API。契约见 docs/接口契约-阶段2.md §5。 */
@RestController
@RequestMapping("/api")
public class ChannelController {

    private final ChannelService channelService;

    public ChannelController(ChannelService channelService) {
        this.channelService = channelService;
    }

    @GetMapping("/drawdown/options")
    public Map<String, Object> options(@RequestParam String channelId, @RequestParam String creditId) {
        return channelService.options(channelId, creditId);
    }

    @PostMapping("/drawdowns")
    public Map<String, Object> applyDrawdown(@RequestParam String channelId, @RequestBody Map<String, Object> request) {
        return channelService.applyDrawdown(channelId, request);
    }

    @GetMapping("/drawdowns/{channelRefNo}")
    public Map<String, Object> drawdownDetail(@PathVariable String channelRefNo) {
        return channelService.drawdownDetail(channelRefNo);
    }

    @PostMapping("/repayments")
    public Map<String, Object> applyRepayment(@RequestParam String channelId, @RequestBody Map<String, Object> request) {
        return channelService.applyRepayment(channelId, request);
    }

    @GetMapping("/repayments/{channelRefNo}")
    public Map<String, Object> repaymentDetail(@PathVariable String channelRefNo) {
        return channelService.repaymentDetail(channelRefNo);
    }

    /** 授信申请入口（阶段 3）：渠道准入后透传中台。 */
    @PostMapping("/credit-applications")
    public Map<String, Object> applyCredit(@RequestParam String channelId, @RequestBody Map<String, Object> request) {
        return channelService.applyCredit(channelId, request);
    }

    @GetMapping("/credit-applications/{channelRefNo}")
    public Map<String, Object> creditApplicationDetail(@PathVariable String channelRefNo) {
        return channelService.creditApplicationDetail(channelRefNo);
    }
}

package com.rsd.simulator;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 外部交易流水：付款（PAYMENT）与扣款（DEDUCTION）。
 * 状态：PROCESSING → SUCCESS | FAILED。回调未送达时中台查单也能取到真实终态（query 永远返回真实状态）。
 * 场景配置挂在 bizOrderNo 上，不混入正式业务字段（边界设计 §7）。
 */
@Entity
@Table(name = "ext_transaction")
public class ExtTransaction {

    public enum Kind { PAYMENT, DEDUCTION, APPROVAL }

    public enum Scenario {
        SYNC_SUCCESS, SYNC_REJECT, ASYNC_SUCCESS_DELAY, ASYNC_FAIL, NO_CALLBACK_NEED_QUERY
    }

    @Id
    private String extSerialNo;
    private Kind kind;
    private String bizOrderNo;
    private BigDecimal amount;
    private String accountName;     // 收款人/付款人
    private String accountNo;
    private String status;          // PROCESSING / SUCCESS / FAILED
    private Scenario scenario;
    private int delaySeconds;
    private LocalDateTime processDueAt;      // 异步结果的产生时间
    private boolean resultResolved;          // 终态是否已产生
    private boolean callbackSuppressed;      // NO_CALLBACK 场景：终态已产生但回调不投递
    private LocalDateTime finishedAt;
    private LocalDateTime createdAt;
    // 审批类交易（APPROVAL）专用：结论与批准额度
    private String resultDetail;    // APPROVED / REJECTED
    private BigDecimal resultAmount; // 批准额度（可能低于申请额度）

    public String getExtSerialNo() { return extSerialNo; }
    public void setExtSerialNo(String extSerialNo) { this.extSerialNo = extSerialNo; }
    public Kind getKind() { return kind; }
    public void setKind(Kind kind) { this.kind = kind; }
    public String getBizOrderNo() { return bizOrderNo; }
    public void setBizOrderNo(String bizOrderNo) { this.bizOrderNo = bizOrderNo; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public String getAccountName() { return accountName; }
    public void setAccountName(String accountName) { this.accountName = accountName; }
    public String getAccountNo() { return accountNo; }
    public void setAccountNo(String accountNo) { this.accountNo = accountNo; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public Scenario getScenario() { return scenario; }
    public void setScenario(Scenario scenario) { this.scenario = scenario; }
    public int getDelaySeconds() { return delaySeconds; }
    public void setDelaySeconds(int delaySeconds) { this.delaySeconds = delaySeconds; }
    public LocalDateTime getProcessDueAt() { return processDueAt; }
    public void setProcessDueAt(LocalDateTime processDueAt) { this.processDueAt = processDueAt; }
    public boolean isResultResolved() { return resultResolved; }
    public void setResultResolved(boolean resultResolved) { this.resultResolved = resultResolved; }
    public boolean isCallbackSuppressed() { return callbackSuppressed; }
    public void setCallbackSuppressed(boolean callbackSuppressed) { this.callbackSuppressed = callbackSuppressed; }
    public LocalDateTime getFinishedAt() { return finishedAt; }
    public void setFinishedAt(LocalDateTime finishedAt) { this.finishedAt = finishedAt; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public String getResultDetail() { return resultDetail; }
    public void setResultDetail(String resultDetail) { this.resultDetail = resultDetail; }
    public BigDecimal getResultAmount() { return resultAmount; }
    public void setResultAmount(BigDecimal resultAmount) { this.resultAmount = resultAmount; }
}

