import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.external.SimulatorClient;
import com.rsd.middle.fineract.FineractClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.Map;

/**
 * 还款编排：订单 → 模拟扣款 → 确认到账 → Fineract 还款入账 → 读取分配明细 → 按本金逐层恢复占用。
 * 规则（docs/三系统边界设计.md §6）：归还利息、费用不恢复本金授信额度；
 * 分配顺序由 Fineract 产品策略决定，中台只保存分配结果，不在多个系统重复判断分配。
 */
@Service
public class RepaymentService {

    private static final Logger log = LoggerFactory.getLogger(RepaymentService.class);

    private final RepaymentOrderRepository orderRepo;
    private final DrawdownOrderRepository drawdownRepo;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final FineractClient fineract;
    private final SimulatorClient simulator;

    public RepaymentService(RepaymentOrderRepository orderRepo, DrawdownOrderRepository drawdownRepo,
                            LimitService limitService, ProductConfigRepository productRepo,
                            FineractClient fineract, SimulatorClient simulator) {
        this.orderRepo = orderRepo;
        this.drawdownRepo = drawdownRepo;
        this.limitService = limitService;
        this.productRepo = productRepo;
        this.fineract = fineract;
        this.simulator = simulator;
    }

    /** 提前结清/部分还本试算：透传 Fineract calculatePrepayment 结果（金额构成见源码核查报告 §1）。 */
    public Map<String, Object> prepaymentQuote(String loanAccountNo, String type, BigDecimal amount) {
        requireLoan(loanAccountNo);
        Map<String, Object> trial = fineract.calculatePrepayment(loanAccountNo, Ids.now().toLocalDate().toString());
        return Map.of("loanAccountNo", loanAccountNo, "type", type,
                "amount", amount == null ? trial.get("amount") : amount, "trial", trial);
    }

    @Transactional
    public RepaymentOrder apply(String loanAccountNo, String payerAccount, String type, BigDecimal amount) {
        requireLoan(loanAccountNo);
        RepaymentOrder order = new RepaymentOrder();
        order.setBizOrderNo(Ids.next("RP-"));
        order.setLoanAccountNo(loanAccountNo);
        order.setCreditId(creditOfLoan(loanAccountNo));
        order.setPayerAccount(payerAccount);
        order.setType(RepaymentOrder.Type.valueOf(type));
        order.setAmount(amount);
        order.setStatus(RepaymentOrder.Status.PROCESSING);
        order.setDeductionStatus(RepaymentOrder.DeductionStatus.TO_SUBMIT);
        order.setCreatedAt(Ids.now());
        order.setUpdatedAt(Ids.now());
        orderRepo.save(order);
        submitDeduction(order);
        return order;
    }

    public void submitDeduction(RepaymentOrder order) {
        try {
            SimulatorClient.PaymentSubmission sub = simulator.submitDeduction(
                    order.getBizOrderNo(), order.getPayerAccount(), order.getAmount());
            order.setExtSerialNo(sub.extSerialNo());
            order.setUpdatedAt(Ids.now());
            switch (sub.status()) {
                case "SUCCESS" -> onDeductionResult(order, "SUCCESS");
                case "REJECTED" -> onDeductionResult(order, "FAILED");
                default -> order.setDeductionStatus(RepaymentOrder.DeductionStatus.PROCESSING);
            }
        } catch (Exception e) {
            log.warn("扣款提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
        }
    }

    /** 扣款结果（回调与查单共用）。幂等：终态订单收到重复结果直接忽略。 */
    @Transactional
    public void onDeductionResult(RepaymentOrder order, String result) {
        if (order.terminal()) {
            return;
        }
        order.setUpdatedAt(Ids.now());
        if ("SUCCESS".equals(result)) {
            if (order.getDeductionStatus() == RepaymentOrder.DeductionStatus.SUCCESS) {
                return;
            }
            order.setDeductionStatus(RepaymentOrder.DeductionStatus.SUCCESS);
            book(order);
        } else {
            if (order.getDeductionStatus() == RepaymentOrder.DeductionStatus.FAILED) {
                return;
            }
            order.setDeductionStatus(RepaymentOrder.DeductionStatus.FAILED);
            order.setStatus(RepaymentOrder.Status.FAILED);
        }
    }

    /** 入账：Fineract 还款交易 + 分配明细 + 本金恢复额度。分配失败不阻断入账记录，转补偿重读。 */
    @Transactional
    public void book(RepaymentOrder order) {
        if (order.getStatus() == RepaymentOrder.Status.SUCCESS) {
            return;
        }
        try {
            String transactionId = fineract.repayLoan(order.getLoanAccountNo(), order.getAmount());
            FineractClient.RepaymentAllocation allocation =

[54 more lines in file. Use offset=121 to continue.]

                    fineract.getRepaymentAllocation(order.getLoanAccountNo(), transactionId);
            order.setFineractTransactionId(allocation.transactionId());
            order.setPrincipalPortion(allocation.principalPortion());
            order.setInterestPortion(allocation.interestPortion());
            order.setFeePortion(allocation.feePortion());
            order.setStatus(RepaymentOrder.Status.SUCCESS);
            order.setUpdatedAt(Ids.now());
            // 只有本金部分逐层恢复授信占用；利息、费用不恢复（担保层按覆盖比例折算）
            DrawdownOrder drawdown = drawdownRepo.findByLoanAccountNo(order.getLoanAccountNo()).orElse(null);
            String productId = drawdown == null ? null : drawdown.getProductId();
            boolean requiresGuarantee = productId == null || productRepo.findById(productId)
                    .map(ProductConfig::isRequiresGuarantee).orElse(false);
            limitService.restoreByPrincipal(order.getCreditId(), order.getBizOrderNo(),
                    order.getLoanAccountNo(), productId, requiresGuarantee, allocation.principalPortion());
        } catch (Exception e) {
            log.warn("还款入账失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
            // 入账失败时订单保持 PROCESSING，补偿任务基于"扣款已成功"重试入账；
            // Fineract 侧重复还款由 adapter 先查交易是否已存在来防重。
        }
    }

    /** 查单收敛（补偿任务用）。 */
    @Transactional
    public void queryAndSettle(RepaymentOrder order) {
        SimulatorClient.ExternalStatus status = simulator.query("DEDUCTION", order.getExtSerialNo());
        if ("SUCCESS".equals(status.status()) || "FAILED".equals(status.status())) {
            onDeductionResult(order, status.status());
        } else if ("RESULT_UNCONFIRMED".equals(status.status())) {
            order.setDeductionStatus(RepaymentOrder.DeductionStatus.RESULT_UNCONFIRMED);
        }
    }

    public Map<String, Object> detail(String bizOrderNo) {
        RepaymentOrder order = orderRepo.findById(bizOrderNo).orElseThrow();
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name(),
                "amount", order.getAmount(),
                "allocation", Map.of("principalPortion", order.getPrincipalPortion() == null ? 0 : order.getPrincipalPortion(),
                        "interestPortion", order.getInterestPortion() == null ? 0 : order.getInterestPortion(),
                        "feePortion", order.getFeePortion() == null ? 0 : order.getFeePortion()));
    }

    private void requireLoan(String loanAccountNo) {
        if (drawdownRepo.findByLoanAccountNo(loanAccountNo).isEmpty()) {
            throw new BizException(BizException.Code.LOAN_NOT_FOUND);
        }
    }

    private String creditOfLoan(String loanAccountNo) {
        return drawdownRepo.findByLoanAccountNo(loanAccountNo)
                .map(DrawdownOrder::getCreditId)
                .orElseThrow(() -> new BizException(BizException.Code.LOAN_NOT_FOUND));
    }
}

